insiderObjects.configureData:
//删除区域
$('#' + id).layout('remove','west')
//删除区域
$('#' + id).layout('remove','north')

// 表格列排序
$('#' + id).datagrid({
    remoteSort: false, // 关闭远程排序，即在本地进行排序
    columns: [ // 列配置
        [
            {
                field: 'name', // 字段名
                title: '场站名称', // 列标题
                width: '50%', // 列宽度
                align: 'center' // 文字对齐方式
            },
            {
                field: 'code', // 字段名
                title: '压力（KPa）', // 列标题
                width: '25%', // 列宽度
                align: 'center' // 文字对齐方式
            },
            {
                field: 'price', // 字段名
                title: '流量（m³/h）', // 列标题
                width: '25%', // 列宽度
                align: 'center', // 文字对齐方式
                sortable: true, // 允许排序
                sort: function(a, b) { // 自定义排序函数
                    if (parseFloat(a)) // 转换为浮点数
                        a = parseFloat(a);
                    if (parseFloat(b)) // 转换为浮点数
                        b = parseFloat(b);
                    return (a > b ? 1 : -1); // 比较大小
                }
            }
        ]
    ]
});

