/*id是easyui控件的id
//domId是包裹easyui控件的外层div的id*/
::-webkit-scrollbar {
    width: 0px;
    height: 0px;
    background-color: #409eff00;
}
/*自动滚动 在使用此功能的时，数据网格的数据要写两遍*/
#domId .datagrid-body {
    overflow-y: hidden;
}
#domId .datagrid-body table{
    position: relative;
    top:0px;
    left:0px;
    animation: mymove 5s infinite linear;  /* 时间自己配合适的值 */
}
#domId .datagrid-body table:hover{
    animation-play-state: paused;
}
@-webkit-keyframes mymove{
    from{top:0px;}
    to{top:-180px;} /* top自己配合适的值 */ 
}

